            rd += (rnd_(length(uv * 100. + u_frame) + vec3(0, .1, .2)) * 2. - 1.) * 1.;
            // rd += normalize(rnd_(length(uv * 100. + u_frame) + vec3(0, .1, .2)) * 2. - 1.) * ${fxrand()+.7};
            rd = reflect(rd, n);
            rd = normalize(rd);

